// Dynamic programming approach to calculate binomial coefficient
if (k < 0 || k > n) { return 0; }
if (k == 0 || k == n) { return 1; }
long[][] dp = new long[n + 1][k + 1];
for (int i = 0; i <= n; i++) { dp[i][0] = 1; }
for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= Math.min(i, k); j++) {
        dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
    }
}
return dp[n][k];

